DO $test$
DECLARE u uuid;bid uuid:=gen_random_uuid();plan uuid;pi uuid:=gen_random_uuid();lt uuid:=gen_random_uuid();dt uuid:=gen_random_uuid();rev timestamptz;bankrev timestamptz;snapshot jsonb;values jsonb;items jsonb;leaves jsonb;docs jsonb;r jsonb;req uuid:=gen_random_uuid();added uuid;denied boolean;before_audit bigint;
BEGIN
 IF public.frindly_market_environment_status()->>'project_ref' IS DISTINCT FROM 'smvvevrtjqkflyqkyape' THEN RAISE EXCEPTION 'Market only';END IF;
 SELECT id INTO u FROM auth.users a WHERE NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=a.id) ORDER BY id LIMIT 1;
 SELECT id INTO plan FROM public.plans WHERE 'payroll'=ANY(included_modules) AND 'bank_reconciliation'=ANY(included_modules) ORDER BY cardinality(included_modules) DESC NULLS LAST LIMIT 1;
 IF u IS NULL OR plan IS NULL THEN RAISE EXCEPTION 'Fixture prerequisites missing';END IF;
 BEGIN
  INSERT INTO public.businesses(id,name) VALUES(bid,'Market atomic settings fixture');
  INSERT INTO public.profiles(id,business_id,active_business_id,full_name,role,is_super_admin) VALUES(u,bid,bid,'Settings fixture','owner',false);
  INSERT INTO public.business_memberships(business_id,user_id,role,status) VALUES(bid,u,'owner','active');
  INSERT INTO public.subscriptions(business_id,plan_id,status,current_period_end,trial_ends_at) VALUES(bid,plan,'trialing',now()+interval '30 days',now()+interval '30 days');
  INSERT INTO public.payroll_settings(business_id) VALUES(bid);
  INSERT INTO public.payroll_pay_items(id,business_id,item_type,name,calculation_type,default_rate) VALUES(pi,bid,'earning','Fixture wages','fixed',20);
  INSERT INTO public.payroll_leave_types(id,business_id,name,paid,statutory_leave_code) VALUES(lt,bid,'Fixture leave',true,'sick_leave');
  INSERT INTO public.payroll_document_types(id,business_id,name,required) VALUES(dt,bid,'Fixture document',false);
  PERFORM set_config('request.jwt.claim.sub',u::text,true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
  EXECUTE 'SET LOCAL ROLE authenticated';
  snapshot:=public.v6227_get_payroll_settings();rev:=(snapshot->'settings'->>'updated_at')::timestamptz;
  IF snapshot->'settings'->>'business_id'<>bid::text OR jsonb_array_length(snapshot->'pay_items')<>1 THEN RAISE EXCEPTION 'Settings snapshot missing';END IF;
  values:=jsonb_build_object('country_code','NZ','currency','NZD','default_pay_frequency','four-weekly','default_pay_day',1,'week_start_day',1,'default_weekly_hours',38,'default_working_days',5,'default_labour_classification','indirect','employee_prefix','FX','payslip_note','Fixture note','payroll_package_identifier','Frindly_v61');
  items:=jsonb_build_array(jsonb_build_object('id',pi,'item_type','earning','name','Updated wages','calculation_type','fixed','default_rate',25,'taxable',true,'statutory_earning_code','ordinary_earnings','holidays_gross_earnings_mode','include','owp_inclusion_mode','include','rdp_inclusion_mode','include','adp_inclusion_mode','include'));
  leaves:=jsonb_build_array(jsonb_build_object('id',lt,'name','Updated leave','paid',true));docs:=jsonb_build_array(jsonb_build_object('id',dt,'name','Updated document','required',true));
  denied:=false;BEGIN PERFORM public.v6227_save_payroll_settings(bid,rev,values,items,leaves,jsonb_set(docs,'{0,id}',to_jsonb(gen_random_uuid())));EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
  IF NOT denied OR (SELECT default_weekly_hours FROM public.payroll_settings WHERE business_id=bid)<>40 OR (SELECT name FROM public.payroll_pay_items WHERE id=pi)<>'Fixture wages' OR (SELECT name FROM public.payroll_leave_types WHERE id=lt)<>'Fixture leave' OR (SELECT updated_at FROM public.payroll_settings WHERE business_id=bid)<>rev THEN RAISE EXCEPTION 'Failed settings save committed partial changes';END IF;
  r:=public.v6227_save_payroll_settings(bid,rev,values,items,leaves,docs);
  IF r->'settings'->>'default_pay_frequency'<>'four-weekly' OR (SELECT name FROM public.payroll_document_types WHERE id=dt)<>'Updated document' OR (SELECT statutory_leave_code FROM public.payroll_leave_types WHERE id=lt)<>'sick_leave' THEN RAISE EXCEPTION 'Settings save lost values or statutory metadata';END IF;
  denied:=false;BEGIN PERFORM public.v6227_save_payroll_settings(bid,rev,values,items,leaves,docs);EXCEPTION WHEN serialization_failure THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Stale save accepted';END IF;
  rev:=(r->'settings'->>'updated_at')::timestamptz;
  denied:=false;BEGIN PERFORM public.v6227_save_payroll_settings(bid,rev,jsonb_set(values,'{default_weekly_hours}','"NaN"'),items,leaves,docs);EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Invalid numeric default accepted';END IF;
  denied:=false;BEGIN UPDATE public.payroll_settings SET employee_prefix='BAD' WHERE business_id=bid;EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Old settings writer accepted';END IF;
  r:=public.v6227_payroll_catalog_command(bid,rev,req,'leave_type','add',NULL,'{"name":"Retry fixture"}');added:=(r->>'id')::uuid;
  PERFORM public.v6227_payroll_catalog_command(bid,rev,req,'leave_type','add',NULL,'{"name":"Retry fixture"}');
  IF (SELECT count(*) FROM public.payroll_leave_types WHERE business_id=bid AND name='Retry fixture')<>1 THEN RAISE EXCEPTION 'Retry created duplicate catalog item';END IF;
  denied:=false;BEGIN PERFORM public.v6227_payroll_catalog_command(bid,rev,req,'leave_type','add',NULL,'{"name":"Changed retry"}');EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Retry changed command';END IF;
  denied:=false;BEGIN PERFORM public.v6227_save_payroll_settings(bid,rev,values,items,leaves,docs);EXCEPTION WHEN serialization_failure THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Catalog edit did not invalidate saved settings revision';END IF;
  SELECT updated_at INTO rev FROM public.payroll_settings WHERE business_id=bid;
  PERFORM public.v6227_payroll_catalog_command(bid,rev,gen_random_uuid(),'leave_type','archive',added,'{}');
  IF NOT (SELECT archived FROM public.payroll_leave_types WHERE id=added) THEN RAISE EXCEPTION 'Archive did not retain the record';END IF;
  r:=public.v6227_save_bank_preferences(bid,NULL,3,90);bankrev:=(r->>'updated_at')::timestamptz;
  IF (r->>'date_tolerance_days')::int<>3 OR (SELECT count(*) FROM public.bank_reconciliation_audit WHERE business_id=bid AND action='preferences_updated')<>1 THEN RAISE EXCEPTION 'Bank preferences or audit missing';END IF;
  denied:=false;BEGIN PERFORM public.v6227_save_bank_preferences(bid,NULL,4,95);EXCEPTION WHEN serialization_failure THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Stale bank preferences overwritten';END IF;
  denied:=false;BEGIN PERFORM public.v6227_save_bank_preferences(bid,bankrev,31,95);EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Invalid bank preferences accepted';END IF;
  denied:=false;BEGIN UPDATE public.bank_reconciliation_settings SET date_tolerance_days=4 WHERE business_id=bid;EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Old bank preferences writer accepted';END IF;
  PERFORM public.v55_seed_payroll_defaults(bid);
  SELECT updated_at INTO rev FROM public.payroll_settings WHERE business_id=bid;
  PERFORM public.v55_seed_payroll_defaults(bid);
  IF (SELECT updated_at FROM public.payroll_settings WHERE business_id=bid) IS DISTINCT FROM rev OR NOT EXISTS(SELECT 1 FROM public.payroll_pay_items WHERE business_id=bid AND name='Ordinary Hours') THEN RAISE EXCEPTION 'Default seeding is broken or changes revision on every read';END IF;
  PERFORM set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
  denied:=false;BEGIN PERFORM public.v6227_payroll_catalog_command(bid,rev,gen_random_uuid(),'document_type','add',NULL,'{"name":"Foreign"}');EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Foreign catalog caller accepted';END IF;
  denied:=false;BEGIN PERFORM public.v6227_save_bank_preferences(bid,bankrev,4,95);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Foreign bank caller accepted';END IF;
  PERFORM set_config('request.jwt.claim.sub',u::text,true);
  EXECUTE 'RESET ROLE';
  UPDATE public.business_memberships SET role='viewer' WHERE business_id=bid AND user_id=u;
  EXECUTE 'SET LOCAL ROLE authenticated';
  denied:=false;BEGIN PERFORM public.v6227_save_payroll_settings(bid,rev,values,items,leaves,docs);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Read-only caller saved payroll settings';END IF;
  denied:=false;BEGIN PERFORM public.v6227_save_bank_preferences(bid,bankrev,4,95);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Read-only caller saved bank preferences';END IF;
  EXECUTE 'RESET ROLE';
  IF has_function_privilege('anon','public.v6227_save_payroll_settings(uuid,timestamptz,jsonb,jsonb,jsonb,jsonb)','EXECUTE') OR has_table_privilege('authenticated','public.payroll_settings_operations','SELECT') THEN RAISE EXCEPTION 'Unsafe settings API grants';END IF;
  RAISE EXCEPTION USING ERRCODE='P6227',MESSAGE='Rollback settings fixtures';
 EXCEPTION WHEN SQLSTATE 'P6227' THEN NULL;END;
 IF EXISTS(SELECT 1 FROM public.businesses WHERE id=bid) THEN RAISE EXCEPTION 'Settings fixture leaked';END IF;
 RAISE NOTICE 'Settings fixture passed; all data rolled back';
END;$test$;
